  ee.Feature(null, {'fase': 'TITULO_ANULADO'}),
  ee.Feature(null, {'fase': 'CCDRU'}),
  ee.Feature(null, {'fase': 'DECRETO'}),
  ee.Feature(null, {'fase': 'PORTARIA'}),
  ee.Feature(null, {'fase': 'TITULADO'}),
  ee.Feature(null, {'fase': 'NAO_INFORMADO'}),
]);

// 2. Chamar a função
