'CCDRU': 1,
'DECRETO': 2,
'NAO_INFORMADO': 3,
'PORTARIA': 4,
'RTID': 5,
'TITULADO': 6,
'TITULO_ANULADO': 7,
'TITULO_PARCIAL': 8,
});

// E então, no passo 4, use:
